/**
 * Test Case: Product Search
 *
 * Tags: @master @regression @web
 *
 * Steps:
 * 1) Search for a known product from the header search box
 * 2) Verify the search results page is displayed
 * 3) Verify the expected product is listed and matches the search criteria
 */

// Generated by GitHub Copilot - Nov-23-2026
import { test, expect } from '../../fixtures/pageFixtures';
import { Helper } from '../../utils/helper';

test('Product search test @master @regression @web', async ({ homePage, searchResultsPage }) => {
    const { productName } = Helper.getProductDetails();

    await test.step('1) Search for the product', async () => {
        await homePage.searchProduct(productName);
    });

    await test.step('2) Verify the search results page is displayed', async () => {
        expect(await searchResultsPage.isSearchResultsPageExists()).toBeTruthy();
    });

    await test.step('3) Verify the expected product is listed', async () => {
        expect(await searchResultsPage.isProductExist(productName)).toBeTruthy();

        const productNames = await searchResultsPage.getProductNames();
        expect(productNames).toContain(productName);
        for (const name of productNames) {
            expect(name.toLowerCase()).toContain(productName.toLowerCase());
        }
    });

    console.log('✅ ✔️ Product search completed successfully!');
});
